sql.where:
c.is_deleted = 0

    AND (c.name LIKE CONCAT('%', #{q.keyword}, '%')
    OR c.teacher LIKE CONCAT('%', #{q.keyword}, '%'))


    AND c.college_id = #{q.collegeId}


    AND c.term = #{q.term}


    AND c.status = #{q.status}


    AND c.owner_id = #{q.ownerId}



    AND EXISTS (
        SELECT 1 FROM course_member cm
        WHERE cm.course_id = c.id
          AND cm.user_id = #{q.memberUserId}
    )

mapper.select:
SELECT
FROM course c LEFT JOIN sys_college col ON col.id = c.college_id
ORDER BY c.created_at DESC, c.id DESC LIMIT #{q.offset}, #{q.pageSize}

SELECT COUNT(1)
FROM course_member
WHERE course_id = #{courseId}
  AND user_id = #{userId}

mapper.delete:
DELETE FROM course_member
WHERE course_id = #{courseId}
  AND user_id = #{userId}

mapper.update:
UPDATE course
SET member_count = member_count + #{delta}
WHERE id = #{courseId}
  AND member_count + #{delta} >= 0
